import { Button } from '@/react/components/ui/Button'
// The three variants: the White primary for the one main action, secondary for the rest, ghost for tools.

export default function Variants() {
  return (
    <div className="flex flex-wrap items-center gap-3">
      <Button>Get 50% off</Button>
      <Button variant="secondary">Explore the product</Button>
      <Button variant="ghost">Compare plans</Button>
    </div>
  )
}

import { Search } from 'lucide-react'
import { Button } from '@/react/components/ui/Button'
// sm, md and lg, and the square icon button (named with aria-label).

export default function Sizes() {
  return (
    <div className="flex flex-wrap items-center gap-3">
      <Button size="sm">Search</Button>
      <Button size="md">Search</Button>
      <Button size="lg">Search</Button>
      <Button icon variant="secondary" aria-label="Search"><Search size={16} strokeWidth={1.5} aria-hidden="true" /></Button>
    </div>
  )
}

import { ArrowUpRight } from 'lucide-react'
import { Button } from '@/react/components/ui/Button'
// Disabled is a dark fill with a gray label, never faded; a link looks like the button it stands for.

export default function States() {
  return (
    <div className="flex flex-wrap items-center gap-3">
      <Button disabled>Start Creator for 50% off</Button>
      <Button variant="secondary" disabled>Explore the product</Button>
      <Button href="#pricing" variant="secondary">See pricing <ArrowUpRight size={16} strokeWidth={1.5} aria-hidden="true" /></Button>
    </div>
  )
}

